mapper.sql:
where o.deleted=0
and o.order_status=#{status}

  and (o.order_no like concat('%',#{keyword},'%') or u.nickname like concat('%',#{keyword},'%')
    or m.merchant_name like concat('%',#{keyword},'%') or i.product_name like concat('%',#{keyword},'%'))

and o.created_at >= #{startTime}
and o.created_at <= #{endTime}

mapper.select:
select  where r.deleted=0
and r.audit_status=#{status}
order by r.requested_at desc limit #{offset},#{size}

select * from (
  select 'PAYMENT' transactionType,p.id transactionId,p.payment_no transactionNo,p.order_id orderId,p.order_no orderNo,
    p.pay_amount amount,p.payment_status status,p.pay_channel channel,coalesce(p.paid_at,p.created_at) occurredAt
  from payment_record p where p.deleted=0
  union all
  select 'REFUND',r.id,r.refund_no,r.order_id,o.order_no,-r.refund_amount,r.refund_status,'REFUND',r.requested_at
  from payment_refund_record r join order_trade o on o.id=r.order_id where r.deleted=0
) x x.transactionType=#{type}
order by x.occurredAt desc limit #{offset},#{size}
